    "ov.p.qte4": "\u9ad8\u7aef\u523b\u610f\u54cd\u4eae\u3002\u4e00\u6761 Rare \u5c31\u662f 400g\uff0c\u8db3\u591f\u4e00\u6b21\u4e70\u4e0b\u524d\u4e94\u7ea7\u5347\u7ea7\uff08\u5408\u8ba1 322g\uff09\u3002\u6253\u4e2d\u4e00\u4e2a\u4e09\u5341\u6beb\u79d2\u7a97\u53e3\uff0c\u5c31\u662f\u4e00\u6574\u5929\u82e6\u5237\u4e0e\u4e00\u6b21\u8d2d\u7269\u4e4b\u65c5\u7684\u5dee\u522b\uFF0C\u8fd9\u4efd\u56de\u62a5\u8ba9\u6b8b\u9177\u7a97\u53e3\u8bfb\u8d77\u6765\u50cf\u673a\u4f1a\uff0c\u800c\u4e0d\u662f\u60e9\u7f5a\u3002",
