    "ov.p.qte5": "\u9c7c\u6570\u636e\u91cc\u4e0a\u7ebf\u4e09\u6863\u3002Epic \u4e0e Legendary \u5df2\u5728 QTE \u4ee3\u7801\u4e2d\u5b58\u5728\uff0c\u540e\u7eed\u6863\u4f4d\u53ea\u9700\u6539\u6570\u636e\uff0c\u4e0d\u5fc5\u5199\u65b0\u4ee3\u7801\u3002",
