    "ov.p.bars3": "\u8fd9\u4e9b\u9608\u503c\u662f\u539f\u59cb\u70b9\u6570\uff0c\u4e0d\u662f\u4e0a\u9650\u767e\u5206\u6bd4\uFF0C\u8fd9\u4e00\u9009\u62e9\u6bd4\u7cfb\u7edf\u91cc\u4efb\u4f55\u5176\u4ed6\u51b3\u5b9a\u90fd\u66f4\u7ba1\u7528\u3002\u8d77\u59cb\u4e0a\u9650 100 \u65f6\uff0c\u8865\u6ee1\u540e\u53ea\u5728\u56de\u590d\u5e26\u505c\u7559\u56db\u79d2\uff1b\u4e70\u5230\u4e0a\u9650 400 \u65f6\uff0c\u505c\u7559\u516d\u5341\u56db\u79d2\uFF0C\u6574\u6574\u4e00\u4e2a\u6e38\u620f\u65e5\u7684\u6cbb\u7597\uff0c\u800c\u4e0d\u662f\u56db\u79d2\u3002\u66f4\u5927\u7684\u7f50\u4e0d\u53ea\u63a8\u8fdf\u9965\u997f\uff0c\u8fd8\u6210\u500d\u62c9\u957f\u4f60\u5904\u4e8e\u56de\u590d\u7684\u65f6\u95f4\uff0c\u4e8e\u662f Supply \u5347\u7ea7\u6210\u4e86\u5546\u5e97\u4ece\u4e0d\u5ba3\u4f20\u7684\u751f\u547d\u5347\u7ea7\u3002",
    "ov.p.bars4": "75 \u4e0e 80 \u4e4b\u95f4\u662f\u6b7b\u533a\uff0c\u751f\u547d\u4e0d\u505a\u4efb\u4f55\u4e8b\u3002\u5b83\u9632\u6b62\u8865\u7ed9\u5728\u8fb9\u754c\u5f98\u5f8a\u65f6\u6761\u5728\u56de\u590d\u4e0e\u8870\u51cf\u95f4\u7ffb\u8f6c\uFF0CHUD \u6309\u79bb\u6563\u5e27\u6b65\u8fdb\uff0c\u6bcf\u79d2\u4e0a\u4e0b\u8df3\u7684\u56fe\u6807\u8bfb\u8d77\u6765\u50cf\u574f\u4e86\uff0c\u800c\u4e0d\u50cf\u7d27\u5f20\u3002",
