    "ov.p.wrecks1": "\u6c89\u8239\u590d\u7528\u9493\u9c7c\u70b9\u7684\u4eba\u53e3\u89c4\u5219\uff1a\u4e16\u754c\u4e2d\u540c\u65f6\u4e09\u4e2a\u3001\u968f\u673a\u843d\u70b9\u3001\u4e00\u65e6\u6d88\u8017\u7acb\u5373\u66ff\u6362\u3002\u4e24\u79cd\u8d34\u56fe\u3002\u649e\u4e0a\u5f97 +50 \u8865\u7ed9\uff0c\u4ee5\u5f53\u524d\u4e0a\u9650\u5c01\u9876\uFF0C\u4e8e\u662f Supply \u5347\u7ea7\u6084\u6084\u62ac\u9ad8\u6c89\u8239\u4ef7\u503c\uff0c\u7f50\u66f4\u5927\uff0c50 \u4e2d\u6ea2\u51fa\u9876\u90e8\u7684\u66f4\u5c11\u3002\u6c89\u8239\u6ca1\u6709\u6d88\u5931\u8ba1\u65f6\uFF0C\u672a\u9886\u53d6\u7684\u6c89\u8239\u4f1a\u7b49\u7740\uff0c\u56e0\u4e3a\u5b83\u662f\u751f\u547d\u66f2\u7ebf\u7ffb\u8138\u65f6\u4f60\u8981\u7ed5\u53bb\u7684\u4e1c\u897f\uff1b\u4f1a\u81ea\u884c\u8fc7\u671f\u7684\u8d44\u6e90\uff0c\u65e0\u6cd5\u7528\u6765\u89c4\u5212\u7ed5\u884c\u3002",
    "ov.p.wrecks2": "\u7b97\u672f\u6545\u610f\u62e7\u7d27\u3002\u6309\u57fa\u7840\u6d88\u8017\uff0c\u4e00\u5929\u8981 307 \u8865\u7ed9\uff0c\u4e00\u8258\u6c89\u8239\u56de 50\uff0c\u4ec5\u76c8\u4e8f\u5e73\u8861\u5c31\u8981\u5927\u7ea6\u6bcf\u5341\u79d2\u5151\u73b0\u4e00\u8258\u3002\u6ca1\u4eba\u80fd\u6301\u7eed\u505a\u5230\uFF0C\u8fd9\u6b63\u662f\u76ee\u7684\uff1a\u5f00\u5c40\u5e94\u50cf\u5728\u8200\u6c34\u6551\u8239\uff0c\u800c Supply \u4e0e Efficiency \u624d\u628a\u614c\u4e71\u53d8\u6210\u771f\u6b63\u80fd\u5e72\u7684\u6d3b\u3002",
